float luminance(vec3 rgb)
{
    return rgb.r * 0.33 + rgb.g * 0.33 + rgb.b * 0.33;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv.y = uv.y;
    vec2 ar = vec2(1.0, iResolution.y / iResolution.x);

    vec3 col = vec3(0.0, 0.0, 0.0);

    const float size = 100.0;
    vec2 uvR = vec2(fract(uv.x * size), fract(uv.y * size * ar.y));
    vec2 uvG = vec2(fract(uv.x * size + 0.33), fract((uv.y * size + 0.33) * ar.y));
    vec2 uvB = vec2(fract(uv.x * size + 0.66), fract((uv.y * size + 0.66) * ar.y));

    vec2 pos = floor(uv * size * ar) / size;
    vec2 posR = pos;
    vec2 posG = floor((uv * size + 0.33) * ar) / size;
    vec2 posB = floor((uv * size + 0.66) * ar) / size;

    float intensityR = texture(iChannel0, (pos / ar) + 0.5 / size).r;
    float intensityG = texture(iChannel0, ((posG) / ar) + (0.5 - 0.33) / size).g;
    float intensityB = texture(iChannel0, ((posB) / ar) + (0.5 - 0.0) / size).b;

    float circleR = float(length(uvR - 0.5) < intensityR * 0.5);
    float circleG = float(length(uvG - 0.5) < intensityG * 0.5);
    float circleB = float(length(uvB - 0.5) < intensityB * 0.5);

    col = vec3(circleR, circleG, circleB);
    if (uv.x > iMouse.x / iResolution.x) col = texture(iChannel0, uv).rgb;

    // Output to screen
    fragColor = vec4(col,1.0);
}
